  var add = [{"title":"天蚕土豆 · 大千世界宇宙总览（跨作品联动）","content":"天蚕土豆的《斗破苍穹》《武动乾坤》《大主宰》《元尊》《万相之王》同属一个宏大宇宙——大千世界。五作以「炎帝萧炎 / 武祖林动 / 主宰牧尘 / 周元始祖 / 洛岚府李洛」为各代之巅，人物与势力在大千世界的更高层面彼此呼应：牧尘主导的大千盟约曾邀炎帝、武祖等共抗域外邪族之主天邪神；元尊时代的圣神黑卵正是天邪神一脉的远祖祸源；万相之王则是大主宰之后的晚辈世代。本界知识库只载本作原著设定，跨作联动仅作「同宇宙背景呼应」，不把别作人物写入本作剧情。","category":"同宇宙联动","tags":["同宇宙联动","大千世界","天蚕土豆","炎帝","武祖","主宰","周元始祖","wanxiangzhiwang"]},{"title":"同宇宙联动 · 萧炎（炎帝，《斗破苍穹》","content":"《斗破苍穹》主角萧炎，尊号炎帝，终至斗帝，定位：斗气大陆崛起，晋斗帝，为炎帝，大千世界巅峰强者之一。本作与之的呼应：《武动乾坤》《大主宰》的林动（武祖）、牧尘（主宰）与萧炎同列大千世界巅峰；萧炎曾以炎帝之身助牧尘迎战天邪神。（仅作同宇宙背景，不写入本作剧情与人物卡）。","category":"同宇宙联动","tags":["同宇宙联动","斗破苍穹","萧炎","炎帝","wanxiangzhiwang"]},{"title":"同宇宙联动 · 林动（武祖，《武动乾坤》","content":"《武动乾坤》主角林动，尊号武祖，终至祖境，定位：自青阳镇崛起，吞八大祖符、战异魔皇，晋祖境，号武祖。本作与之的呼应：林动（武祖）与萧炎（炎帝）、牧尘（主宰）同列大千世界巅峰，曾跨界共抗域外邪族；其时代在元尊之后、大主宰之前。（仅作同宇宙背景，不写入本作剧情与人物卡）。","category":"同宇宙联动","tags":["同宇宙联动","武动乾坤","林动","武祖","wanxiangzhiwang"]},{"title":"同宇宙联动 · 牧尘（主宰，《大主宰》","content":"《大主宰》主角牧尘，尊号主宰，终至主宰境，定位：大千世界第一人，牧府之主，曾率大千盟约迎战域外邪族之主天邪神。本作与之的呼应：牧尘（主宰）主导大千盟约，邀炎帝萧炎、武祖林动共抗天邪神；其父牧锋源自大千世界，与元尊周元始祖、万相之王李洛同属一脉宇宙的后辈传奇。（仅作同宇宙背景，不写入本作剧情与人物卡）。","category":"同宇宙联动","tags":["同宇宙联动","大主宰","牧尘","主宰","wanxiangzhiwang"]},{"title":"同宇宙联动 · 周元（周元始祖，《元尊》","content":"《元尊》主角周元，尊号周元始祖，终至神祇，定位：更早时代的先辈，成神祇号周元始祖，破圣族（圣神）之困，其时代远在斗破/武动/大主宰之前。本作与之的呼应：周元（周元始祖）时代远早于其余四作，所破之圣神黑卵正是《大主宰》域外邪族之主天邪神一脉的远祖祸源；成神祇后号周元始祖，为后世大千世界的先辈根基。（仅作同宇宙背景，不写入本作剧情与人物卡）。","category":"同宇宙联动","tags":["同宇宙联动","元尊","周元","周元始祖","wanxiangzhiwang"]}];
